// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation.select;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.explanation.GenericPlanNode;
import org.eclipse.rdf4j.query.explanation.StrategyDecision;

/**
 * Test-side view of the strategy decisions a query explanation carries. One {@link RecordedDecision} is produced per
 * {@link StrategyDecision} found anywhere in the plan tree, tagged with the path of plan-node types that leads to it so
 * two decisions at different nodes stay distinguishable. The recorder reads only the public explain model, so it works
 * unchanged against the old arbiter and against the rewritten selector.
 */
public final class DecisionRecorder {

	/** One strategy decision as the explanation reported it. */
	public record RecordedDecision(String nodePath, String decisionPoint, String mode, String selected,
			String fallback, String reason, List<String> offered, List<String> declined) {

		/** Stable single-line rendering used by golden fixtures: no timestamps, no free-text reasons. */
		public String fixtureLine() {
			return nodePath + "\t" + decisionPoint + "\t" + mode + "\t" + (selected == null ? "-" : selected) + "\t"
					+ (fallback == null ? "-" : fallback) + "\t" + String.join(",", offered) + "\t"
					+ String.join(",", declined);
		}
	}

	private final List<RecordedDecision> decisions;

	private DecisionRecorder(List<RecordedDecision> decisions) {
		this.decisions = List.copyOf(decisions);
	}

	/** Collects every strategy decision in the explanation tree rooted at {@code root}, in plan order. */
	public static DecisionRecorder capture(GenericPlanNode root) {
		List<RecordedDecision> out = new ArrayList<>();
		collect(root, "", out);
		return new DecisionRecorder(out);
	}

	private static void collect(GenericPlanNode node, String parentPath, List<RecordedDecision> out) {
		if (node == null) {
			return;
		}
		String path = parentPath.isEmpty() ? node.getType() : parentPath + "/" + node.getType();
		if (node.getStrategyDecisions() != null) {
			for (StrategyDecision decision : node.getStrategyDecisions()) {
				out.add(toRecorded(path, decision));
			}
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collect(child, path, out);
			}
		}
	}

	private static RecordedDecision toRecorded(String path, StrategyDecision decision) {
		List<String> offered = decision.candidates()
				.stream()
				.filter(candidate -> !Boolean.FALSE.equals(candidate.canAttempt()))
				.map(StrategyDecision.Candidate::strategy)
				.collect(Collectors.toList());
		List<String> declined = decision.candidates()
				.stream()
				.filter(candidate -> Boolean.FALSE.equals(candidate.canAttempt()))
				.map(StrategyDecision.Candidate::strategy)
				.collect(Collectors.toList());
		return new RecordedDecision(path, decision.decisionPoint(), decision.mode(), decision.wouldSelect(),
				decision.fallback(), decision.reason(), offered, declined);
	}

	public List<RecordedDecision> decisions() {
		return decisions;
	}

	/** Decisions whose decision point contains {@code pointFragment} (for example {@code "GROUP BY"}). */
	public List<RecordedDecision> at(String pointFragment) {
		return decisions.stream()
				.filter(decision -> decision.decisionPoint().contains(pointFragment))
				.collect(Collectors.toList());
	}

	/** Asserts that at least one decision at the given point selected {@code strategy}. */
	public void assertSelected(String pointFragment, String strategy) {
		List<RecordedDecision> matching = at(pointFragment);
		assertThat(matching).as("decisions at %s in %s", pointFragment, decisions).isNotEmpty();
		assertThat(matching.stream().map(RecordedDecision::selected).filter(Objects::nonNull))
				.as("selected strategy at %s; decisions: %s", pointFragment, matching)
				.contains(strategy);
	}

	/** Asserts that {@code strategy} was offered (admitted) at the given point in at least one decision. */
	public void assertOffered(String pointFragment, String strategy) {
		assertThat(at(pointFragment).stream().flatMap(decision -> decision.offered().stream()))
				.as("offered strategies at %s; decisions: %s", pointFragment, at(pointFragment))
				.contains(strategy);
	}

	/** Asserts that {@code strategy} was declined at the given point in at least one decision. */
	public void assertDeclined(String pointFragment, String strategy) {
		assertThat(at(pointFragment).stream().flatMap(decision -> decision.declined().stream()))
				.as("declined strategies at %s; decisions: %s", pointFragment, at(pointFragment))
				.contains(strategy);
	}

	/** The fixture rendering of every decision, one line each, in plan order. */
	public List<String> fixtureLines() {
		return decisions.stream().map(RecordedDecision::fixtureLine).collect(Collectors.toList());
	}
}
